<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;
class AssetLoan extends Model{protected $fillable=['asset_id','borrower_name','borrower_role','borrower_phone','quantity','loan_date','expected_return_date','returned_at','purpose','notes','status','return_condition','return_notes','created_by','returned_by'];protected $casts=['loan_date'=>'date','expected_return_date'=>'date','returned_at'=>'datetime'];public function asset():BelongsTo{return $this->belongsTo(Asset::class);}public function creator():BelongsTo{return $this->belongsTo(User::class,'created_by');}public function returner():BelongsTo{return $this->belongsTo(User::class,'returned_by');}public function getDisplayStatusAttribute():string{return !$this->returned_at&&$this->expected_return_date?->isBefore(today())?'terlambat':$this->status;}public function getStatusLabelAttribute():string{return match($this->display_status){'dipinjam'=>'Dipinjam','dikembalikan'=>'Dikembalikan','terlambat'=>'Terlambat'};}}
